#include <iostream>
#include <string>
using namespace std;

int count_delimiters(const string &data, char delimiter) {
    int count = 0;
    for (size_t i = 0; i < data.length(); i++) {
        if (data[i] == delimiter) {
            count++;
        }
    }
    return count;
}

int main() {
    string line;
    cin >> line;

    int c = count_delimiters(line, ',');
    cout << "DELIMITER COUNT: " << c << endl;
    return 0;
}

