#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;

    int speed = 0;
    int altitude = 0;
    int heading = 0;

    for (int i = 0; i < n; i++) {
        string packet;
        cin >> packet;
        size_t sep = packet.find(':');
        if (sep != string::npos) {
            string verb = packet.substr(0, sep);
            int val = stoi(packet.substr(sep + 1));
            if (verb == "THRUST") {
                speed += val;
            } else if (verb == "ELEVATION") {
                altitude = val;
            } else if (verb == "YAW") {
                heading += val;
            }
        }
    }

    cout << "FINAL SPEED: " << speed << endl;
    cout << "FINAL ALTITUDE: " << altitude << endl;
    cout << "FINAL HEADING: " << heading << endl;
    return 0;
}

